  function clearUnreadMarker(){unreadMessageId=null;ui.stream.querySelector('.unread-divider')?.remove()}
  async function saveReadPosition(timestamp){if(!currentRoom||!user||!timestamp)return;const next=new Date(timestamp),saved=lastReadAt?new Date(lastReadAt):null;if(saved&&next<=saved)return;const roomId=currentRoom.id;const {error}=await db.from('room_read_states').upsert({room_id:roomId,user_id:user.id,last_read_at:next.toISOString(),updated_at:new Date().toISOString()},{onConflict:'room_id,user_id'});if(error){notify(`Could not save read position: ${error.message}`);return}if(currentRoom?.id===roomId)lastReadAt=next.toISOString()}
  function queueReadPosition(){if(!currentRoom||!user||!lastMessageAt||document.hidden||!document.hasFocus()||!atMessageBottom())return;clearUnreadMarker();clearTimeout(readSaveTimer);const timestamp=lastMessageAt;readSaveTimer=setTimeout(()=>saveReadPosition(timestamp),250)}
