    if(!room.is_private){const {error:joinError}=await db.from('room_members').upsert({room_id:room.id,user_id:user.id},{onConflict:'room_id,user_id',ignoreDuplicates:true});if(joinError){notify(joinError.message);return}}
    await loadRoomAssets(room.id);await applyCustomRoomBackground(room);
    const {data:readState,error:readError}=await db.from('room_read_states').select('last_read_at').eq('room_id',room.id).eq('user_id',user.id).maybeSingle();if(readError)notify(`Could not load read position: ${readError.message}`);lastReadAt=readState?.last_read_at||'';
    const recentQuery=db.from('messages').select('*').eq('room_id',room.id).order('created_at',{ascending:true}).limit(100);
    const unreadQuery=lastReadAt?db.from('messages').select('*').eq('room_id',room.id).gt('created_at',lastReadAt).order('created_at',{ascending:true}).limit(500):Promise.resolve({data:[],error:null});
    const [recentResult,unreadResult]=await Promise.all([recentQuery,unreadQuery]);if(recentResult.error){notify(`Could not load messages: ${recentResult.error.message}`);return}if(unreadResult.error)notify(`Could not load unread messages: ${unreadResult.error.message}`);
    const messages=[...new Map([...(recentResult.data||[]),...(unreadResult.data||[])].map(message=>[message.id,message])).values()].sort((a,b)=>new Date(a.created_at)-new Date(b.created_at)||a.id.localeCompare(b.id));
    const firstUnread=lastReadAt?messages.find(message=>new Date(message.created_at)>new Date(lastReadAt)):null;unreadMessageId=firstUnread?.id||null;messages.forEach(appendMessage);lastMessageAt=messages.at(-1)?.created_at||'';if(!lastReadAt)await saveReadPosition(lastMessageAt||'1970-01-01T00:00:00.000Z');
    if(firstUnread)scrollToMessage(firstUnread.id);else{ui.stream.scrollTop=ui.stream.scrollHeight;if(lastMessageAt)queueReadPosition()}
    roomChannel=db.channel(`room-${room.id}`,{config:{presence:{key:user.id}}});
