      // Read in a separate request so the creator-membership trigger has committed
      // before the private-room SELECT policy is evaluated.
      const {data,error}=await db.from('rooms').select('id,name,description,created_at,is_private,invite_code,created_by,theme_id,custom_background_path,logo_path').eq('name',name).eq('created_by',user.id).single();
